SELECT r.alarm_no, r.rule_id, r.instance_id, i.instance_name, i.host_ip, i.redis_port, r.metric_name, r.alarm_level, r.alarm_content, r.trigger_value, r.threshold, r.unit, r.trigger_time, r.recover_time, r.recover_status FROM alarm_record r LEFT JOIN redis_instance i ON r.instance_id = i.instance_id WHERE 1=1 AND r.instance_id = #{instanceId} AND r.alarm_level = #{alarmLevel} AND r.metric_name = #{metricKey} AND r.recover_status = #{recoverStatus}
AND (r.alarm_no LIKE CONCAT('%',#{keyword},'%') OR r.alarm_content LIKE CONCAT('%',#{keyword},'%'))
AND r.trigger_time BETWEEN #{startTime} AND #{endTime} ORDER BY r.trigger_time DESC

SELECT COUNT(*) FROM alarm_record r
WHERE 1=1
AND r.instance_id = #{instanceId}
AND r.alarm_level = #{alarmLevel}
AND r.metric_key = #{metricKey}
AND r.recover_status = #{recoverStatus}

    AND (r.alarm_no LIKE CONCAT('%',#{keyword},'%') OR r.alarm_content LIKE CONCAT('%',#{keyword},'%'))

AND r.trigger_time BETWEEN #{startTime} AND #{endTime}
